import re
from collections import Counter
# extract all organisation-ish names: capitalized sequences possibly with spaces
def names(doc):
    # find sequences of Capitalized words (2+ words) or single capitalized tokens that look like orgs
    cands = re.findall(r"\b([A-Z][a-z]+(?:[A-Z][a-z]+)+)\b", doc)
    return cands
cnt = Counter()
for d in docs:
    for c in names(d):
        cnt[c]+=1
for k,v in cnt.most_common(40):
    print(v,k)

